const iconPaths={home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',brief:'<rect x="5" y="4" width="14" height="17" rx="2"/><rect x="9" y="2" width="6" height="4" rx="1"/><path d="M9 11h6m-6 4h6"/>',quote:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 7h8m-8 5h2m4 0h2m-8 4h2m4 0h2"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6m10-6v6M3 11h18"/>',building:'<path d="M4 21V4h12v17m0-10h4v10M2 21h20M8 8h4m-4 4h4m-4 4h4"/>',chart:'<path d="M3 3v18h18M7 16v-4m5 4V7m5 9V4"/>',people:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-17a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5v2"/>',layers:'<path d="m12 3 10 5-10 5L2 8zm-10 9 10 5 10-5M2 16l10 5 10-5"/>',check:'<path d="m5 12 4 4L19 6"/>',expand:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>'};
function paintIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true">${iconPaths[el.dataset.icon]||iconPaths.brief}</svg>`)}paintIcons();
// Decorative reflection only: excluded from assistive technology and interaction.
const reflection=document.createElement('div');reflection.className='dashboard-reflection';reflection.setAttribute('aria-hidden','true');reflection.setAttribute('inert','');reflection.append(document.querySelector('.dashboard').cloneNode(true));document.querySelector('.dashboard-wrap').append(reflection);
const header=document.querySelector('.header');function updateHeader(){header.classList.toggle('scrolled',scrollY>25)}updateHeader();addEventListener('scroll',updateHeader,{passive:true});
const menuButton=document.querySelector('.menu-toggle'),mobileNav=document.querySelector('#mobile-nav');function closeMenu(){mobileNav.hidden=true;menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Abrir menu')}menuButton.addEventListener('click',()=>{const open=mobileNav.hidden;mobileNav.hidden=!open;menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'Fechar menu':'Abrir menu')});mobileNav.querySelectorAll('a,button').forEach(el=>el.addEventListener('click',closeMenu));addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});matchMedia('(min-width:601px)').addEventListener('change',e=>{if(e.matches)closeMenu()});
const reduced=matchMedia('(prefers-reduced-motion: reduce)');if(!reduced.matches&&'IntersectionObserver'in window){document.documentElement.classList.add('js-motion');const obs=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');obs.unobserve(entry.target)}})},{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>obs.observe(el))}
const flows=[{tag:'O ponto de partida',title:'Um briefing que dá contexto.',description:'Reúna objetivo, destino, período e serviços. Cada nova versão mantém o histórico do que foi solicitado.',label:'Briefing do projeto',badge:'V1',icon:'brief',rows:[['Objetivo','Encontro de lideranças'],['Destino','São Paulo, SP'],['Serviços','Hospedagem · Salas · Transfers']]},{tag:'As possibilidades na mesa',title:'O mesmo escopo para os fornecedores.',description:'Selecione parceiros e compartilhe uma versão do briefing por link. Reúna as respostas e organize os itens da cotação.',label:'Lote de cotação',badge:'Briefing V1',icon:'quote',rows:[['Hospedagem','Fornecedor selecionado'],['Salas e A&B','Resposta recebida'],['Transfers','Aguardando resposta']]},{tag:'Uma decisão com contexto',title:'Uma proposta, uma versão.',description:'Consolide os itens em uma proposta. A versão publicada preserva os valores e permite registrar aprovação, rejeição ou pedido de ajustes.',label:'Proposta do projeto',badge:'V2',icon:'check',rows:[['Escopo','Hospedagem + salas'],['Versão','Publicada para avaliação'],['Próximo passo','Decisão do cliente']]},{tag:'O próximo passo definido',title:'Do aprovado ao planejado.',description:'Organize atividades e prazos para dar continuidade ao projeto. Acompanhe as tarefas e mantenha o contexto das decisões.',label:'Planejamento do projeto',badge:'Em andamento',icon:'calendar',rows:[['Rooming list','Em revisão'],['Agenda do evento','A confirmar'],['Briefing técnico','Planejado']]}];
function setFlow(n){const f=flows[n];document.querySelectorAll('[data-workflow]').forEach((b,i)=>{b.classList.toggle('active',i===n);b.setAttribute('aria-selected',String(i===n));b.tabIndex=i===n?0:-1});const panel=document.querySelector('#step-panel');panel.setAttribute('aria-labelledby',`step-${n}`);panel.innerHTML=`<span class="panel-tag">${f.tag}</span><h3>${f.title}</h3><p>${f.description}</p><div class="mini-brief"><div class="mini-brief-head"><i data-icon="${f.icon}"></i><span>${f.label}</span><span class="badge">${f.badge}</span></div>${f.rows.map(([a,b])=>`<div><span>${a}</span><b>${b}</b></div>`).join('')}</div><small class="illustration-label">Exemplo ilustrativo do fluxo</small>`;paintIcons(panel)}
document.querySelectorAll('[data-workflow]').forEach(b=>b.addEventListener('click',()=>setFlow(Number(b.dataset.workflow))));document.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>setFlow(Number(b.dataset.step))));
let currentTab='etapas';function setProductTab(name){currentTab=name;document.querySelectorAll('[data-tab]').forEach(b=>{const active=b.dataset.tab===name;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;document.querySelector(`#panel-${b.dataset.tab}`).hidden=!active})}
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>setProductTab(b.dataset.tab)));document.querySelectorAll('[data-select-tab]').forEach(a=>a.addEventListener('click',()=>setProductTab(a.dataset.selectTab)));
document.querySelectorAll('[role=tablist]').forEach(list=>list.addEventListener('keydown',e=>{const keys=['ArrowRight','ArrowLeft','ArrowDown','ArrowUp','Home','End'];if(!keys.includes(e.key))return;e.preventDefault();const tabs=[...list.querySelectorAll('[role=tab]')];let i=tabs.indexOf(document.activeElement);if(i<0)return;i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(['ArrowRight','ArrowDown'].includes(e.key)?1:-1)+tabs.length)%tabs.length;tabs[i].focus();tabs[i].click()}));
const login=document.querySelector('#login-dialog');document.querySelectorAll('[data-open-login]').forEach(b=>b.addEventListener('click',()=>login.showModal()));document.querySelector('#explore-from-login').addEventListener('click',()=>{login.close();document.querySelector('#produto').scrollIntoView({behavior:reduced.matches?'instant':'smooth'})});
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close-dialog').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
document.querySelector('#expand-preview').addEventListener('click',()=>{const source=document.querySelector(`#panel-${currentTab} img`),target=document.querySelector('#expanded-image');target.src=source.src;target.alt=source.alt;document.querySelector('#image-dialog').showModal()});
